from typing import List


class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        weights = set()

        for a, b, w in edges:
            rev[b].append((a, w))
            weights.add(w)

        def can(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1

            while stack:
                node = stack.pop()
                for nxt, w in rev[node]:
                    if w <= limit and not seen[nxt]:
                        seen[nxt] = True
                        count += 1
                        stack.append(nxt)

            return count == n

        weights = sorted(weights)
        if not can(weights[-1]):
            return -1

        left, right = 0, len(weights) - 1
        while left < right:
            mid = (left + right) // 2
            if can(weights[mid]):
                right = mid
            else:
                left = mid + 1

        return weights[left]
